import {calculate} from './domain.js';import {api} from './api.js';
const app=document.querySelector('#app');const money=n=>Math.round(n).toLocaleString('ru-RU')+' ₽';const state={amount:1500000,months:24,purpose:'Оборотные средства'};
let signedIn=false;
try{signedIn=sessionStorage.getItem('alfa-demo-session')==='test'}catch{}
function setSession(value){signedIn=value;try{value?sessionStorage.setItem('alfa-demo-session','test'):sessionStorage.removeItem('alfa-demo-session')}catch{}}
const arrow='<img src="assets/arrow.svg" alt="">';
function calculator(){return `<div class="calculator"><div class="fields"><div class="field"><label for="purpose">На что нужны деньги</label><select id="purpose"><option>Оборотные средства</option><option>Оборудование</option><option>Развитие бизнеса</option></select></div><div class="field"><label for="amount">Сумма кредита</label><div class="field-value" id="amountValue"></div><input id="amount" type="range" min="100000" max="10000000" step="50000" value="${state.amount}"><div class="ends"><span>100 тыс. ₽</span><span>10 млн ₽</span></div></div><div class="field"><label for="months">Срок кредита</label><div class="field-value" id="monthsValue"></div><input id="months" type="range" min="6" max="60" value="${state.months}"><div class="ends"><span>6 месяцев</span><span>60 месяцев</span></div></div></div><div class="result"><label>Ежемесячный платёж</label><div class="payment" id="payment" aria-live="polite"></div><div class="stats"><div><label>Условная ставка</label><b id="rate"></b></div><div><label>Переплата</label><b id="interest"></b></div></div><a class="button" href="#/login">Подобрать кредит ${arrow}</a><p class="fine">Предварительный расчёт на демонстрационных условиях. Не оферта. Итоговую ставку и условия определяет банк после рассмотрения заявки. Комиссии и страхование не учтены.</p></div></div>`}
function bindCalc(){document.querySelector('#purpose').value=state.purpose;const update=()=>{state.amount=+document.querySelector('#amount').value;state.months=+document.querySelector('#months').value;state.purpose=document.querySelector('#purpose').value;const r=calculate(state.amount,state.months,state.purpose);document.querySelector('#amountValue').textContent=money(state.amount);document.querySelector('#monthsValue').textContent=state.months+' мес.';document.querySelector('#payment').textContent=money(r.payment);document.querySelector('#rate').textContent=r.rate.toLocaleString('ru-RU')+' %';document.querySelector('#interest').textContent=money(r.interest)};['amount','months','purpose'].forEach(id=>document.getElementById(id).addEventListener('input',update));update()}
const steps=`<div class="steps"><div class="step"><span class="number">01 / ПОДБОР</span><h3>Начните с задачи бизнеса</h3><p>Выберите цель, сумму и комфортный срок. Посмотрите предварительный расчёт.</p></div><div class="step"><span class="number">02 / ЗАЯВКА</span><h3>Расскажите о компании</h3><p>Укажите данные бизнеса в кабинете. Параметры кредита уже будут заполнены.</p></div><div class="step"><span class="number">03 / РЕЗУЛЬТАТ</span><h3>Следите за решением</h3><p>Статус заявки и дальнейшие действия — в одном месте, без лишних звонков.</p></div></div>`;
function shell(content,active='cabinet'){return `<div class="banner">Демонстрационный кабинет · Тестовый аккаунт · Используйте только вымышленные данные</div><div class="workspace"><aside class="sidebar">${[['cabinet','Обзор'],['select','Подобрать кредит'],['applications','Мои заявки']].map(([path,label])=>`<a class="${active===path?'active':''}" href="#/${path}">${label}</a>`).join('')}<a href="#/logout">Выйти</a></aside><section>${content}</section></div>`}
const title=(a,b)=>`<div class="page-title"><div class="eyebrow">Умный кредитный кабинет</div><h1>${a}</h1><p>${b}</p></div>`;
async function render(){let route=location.hash.slice(2)||'';
if(route==='logout'){setSession(false);location.hash='/';return}
if(['cabinet','select','applications','apply'].includes(route)&&!signedIn){location.hash='/login';return}
const accountLink=document.querySelector('header > .button');
accountLink.href='#/login';
accountLink.hidden=signedIn;
accountLink.innerHTML='Войти '+arrow;

if(!route){app.innerHTML=`<section class="hero"><div><div class="eyebrow">Финансирование для бизнеса</div><h1>Ваш бизнес.<br>Ваши планы.<br><em>Наше решение.</em></h1><p>От идеи до заявки на кредит — в одном кабинете. Выберите финансирование под задачи вашего бизнеса.</p><a class="button" href="#/login">Подобрать кредит ${arrow}</a></div><div class="hero-art" aria-hidden="true"><div class="orb"></div><div class="credit-card"><b>А</b><span>НА РАЗВИТИЕ ВАШЕГО БИЗНЕСА</span><strong>Большие планы — ближе.</strong></div><div class="float"><b><span class="dot">●</span> Всё под контролем</b>От подбора до решения</div></div></section><div class="section-head"><h2>Рассчитайте возможности</h2><p>Начните с комфортного платежа</p></div>${calculator()}<div class="section-head"><h2>Три шага к вашим планам</h2><a href="#/guide">Подробнее →</a></div>${steps}`;bindCalc()}
else if(route==='guide'){app.innerHTML=title('Понятный путь к финансированию','Каждый этап — в вашем кабинете.')+steps+`<details open><summary>Что понадобится для заявки?</summary><p>Цель, сумма, срок, название и ИНН компании, сведения о выручке. В прототипе вводите только синтетические данные.</p></details><details><summary>Как определяется ставка?</summary><p>Калькулятор использует условные ставки 19,5% и 21,5%. Реальная оценка и кредитное решение будут выполняться backend-сервисом.</p></details><details><summary>Что умеет ИИ-ассистент?</summary><p>Пока это заглушка. После подключения он сможет помогать с выбором продукта и объяснять условия.</p></details><p><a href="#/login" class="button">Перейти к подбору</a></p>`}
else if(route==='login'){app.innerHTML=`<section class="login-panel panel"><div class="eyebrow">Умный кредитный кабинет</div><h1>Войти в аккаунт</h1><p>Выберите аккаунт, чтобы продолжить</p><button id="test-account" class="account-choice"><span class="avatar">ТА</span><span>Тестовый аккаунт<small>Демонстрационный профиль</small></span>${arrow}</button><button class="secondary other-account" disabled>Другой</button><p class="fine">Вход в другой аккаунт пока недоступен</p><a href="#/" class="back-link">Вернуться на главную</a></section>`;document.querySelector('#test-account').onclick=()=>{setSession(true);location.hash='/cabinet'}}
else if(route==='cabinet'||route==='select'){app.innerHTML=shell(title('Здравствуйте!','Вы вошли как Тестовый аккаунт. Выберите финансирование для своего бизнеса.')+`<div class="panel red-panel"><div class="row"><div><h2>От задачи — к решению</h2><p>Расскажите о планах ИИ-ассистенту, чтобы подобрать кредит.</p></div><a class="button" href="#/select">Подобрать кредит ${arrow}</a></div></div><div class="section-head"><h2>Кредиты для бизнеса</h2></div><div class="cards credit-types"><article class="panel"><span class="number">01</span><h3>Оборотный кредит</h3><p>Для закупки товаров, расчётов с поставщиками и текущих расходов бизнеса.</p></article><article class="panel"><span class="number">02</span><h3>Инвестиционный кредит</h3><p>Для покупки оборудования, расширения производства и развития новых направлений.</p></article><article class="panel"><span class="number">03</span><h3>Кредитная линия</h3><p>Для регулярного финансирования: используйте средства частями в пределах лимита.</p></article><article class="panel"><span class="number">04</span><h3>Овердрафт</h3><p>Для краткосрочных кассовых разрывов, когда поступления ещё впереди.</p></article></div><p class="fine">Общие типы финансирования для знакомства. Доступность и условия определяются банком.</p>`,route==='select'?'select':'cabinet');
if(route==='select'){const dialog=document.createElement('dialog');dialog.className='assistant-dialog';dialog.setAttribute('aria-labelledby','assistant-title');dialog.innerHTML=`<div class="row"><div><span class="tag">Заглушка · ИИ пока не подключён</span><h2 id="assistant-title">Подберём кредит вместе</h2></div><button class="secondary close-dialog" aria-label="Закрыть диалог">×</button></div><p>Расскажите, на что нужны средства и что важно для вашего бизнеса.</p><div class="chat-log" role="log" aria-live="polite"><div class="chat-message">Здравствуйте! Здесь будет ваш ИИ-ассистент по подбору кредита. Пока можно познакомиться с диалогом — ответы демонстрационные.</div></div><div class="chips"><button type="button">Нужны деньги на закупку товара</button><button type="button">Хочу приобрести оборудование</button></div><form id="chat"><label class="sr-only" for="chat-input">Сообщение ассистенту</label><input id="chat-input" placeholder="Расскажите о вашей задаче" maxlength="1000" required><button>Отправить</button></form>`;app.append(dialog);dialog.showModal();dialog.querySelector('.close-dialog').onclick=()=>{location.hash='/cabinet'};dialog.addEventListener('cancel',e=>{e.preventDefault();location.hash='/cabinet'});const ask=async text=>{if(!text.trim())return;const log=dialog.querySelector('.chat-log');for(const value of [text,(await api.assistant()).message]){const el=document.createElement('div');el.className='chat-message';el.textContent=value;log.append(el)}log.scrollTop=log.scrollHeight};dialog.querySelector('#chat').onsubmit=e=>{e.preventDefault();const input=e.target.querySelector('input');ask(input.value);input.value=''};dialog.querySelectorAll('.chips button').forEach(b=>b.onclick=()=>ask(b.textContent))}}
else if(route==='apply'){app.innerHTML=shell(title('Заявка на финансирование','Шаг 2 из 3 · Расскажите о вашем бизнесе')+`<div class="panel"><div class="row"><h3>${money(state.amount)} · ${state.months} мес.</h3><a href="#/select">Изменить</a></div><p>${state.purpose}</p><form id="application" class="form-grid"><label>Название компании<input name="company" placeholder="ООО «Пример»" maxlength="120" required></label><label>ИНН компании<input name="inn" inputmode="numeric" pattern="([0-9]{10}|[0-9]{12})" title="10 или 12 цифр" placeholder="0000000000" required></label><label>Выручка в месяц, ₽<input name="revenue" type="number" min="1" max="100000000000" required></label><label>Срок работы бизнеса, месяцев<input name="ageMonths" type="number" min="1" max="1200" required></label><label class="full"><span><input type="checkbox" required> Подтверждаю, что использую вымышленные данные для демонстрации</span></label><p class="fine full">Данные сохраняются только в этом браузере. Заявка не отправляется в банк.</p><div class="full"><button>Отправить демозаявку</button><p role="alert" id="error"></p></div></form></div>`,'select');document.querySelector('#application').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const data=Object.fromEntries(new FormData(e.target));await api.createApplication({...data,revenue:+data.revenue,ageMonths:+data.ageMonths,...state});location.hash='/applications'}catch{document.querySelector('#error').textContent='Не удалось сохранить заявку. Проверьте доступность хранилища браузера.';b.disabled=false}}}
else if(route==='applications'){app.innerHTML=shell(title('Мои заявки','Статусы и следующие шаги — всегда под рукой.')+'<div id="applications" class="list">Загружаем…</div>','applications');const items=await api.listApplications();const list=document.querySelector('#applications');if(!list)return;list.innerHTML=items.length?'':`<div class="panel"><h3>Пока здесь пусто</h3><p>Подберите кредит и отправьте первую демонстрационную заявку.</p><a href="#/select" class="button">Подобрать кредит</a></div>`;for(const item of items){const el=document.createElement('article');el.className='panel';el.innerHTML=`<div class="row"><h3></h3><span class="status">Отправлена · демо</span></div><p></p><div class="timeline"><span class="done">1. Заявка отправлена</span><span>2. Проверка</span><span>3. Решение</span></div><p class="fine">Следующий шаг: проверка данных. Изменение статусов станет доступно после подключения backend. Реальное рассмотрение не выполняется.</p>`;el.querySelector('h3').textContent=item.purpose+' · '+money(item.amount);el.querySelector('p').textContent=item.company+' · '+item.months+' мес. · '+new Date(item.createdAt).toLocaleDateString('ru-RU');list.append(el)}}
else{app.innerHTML=title('Страница не найдена','Вернитесь на главную, чтобы продолжить.')+'<a class="button" href="#/">На главную</a>'}window.scrollTo(0,0)}
window.addEventListener('hashchange',render);render();
